use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    // k is 1-based, and we assume 1 <= k < list.len()
    requires
        list.len() >= 2,
        1 <= k,
        k < list.len(),
    ensures
        new_list.len() == list.len() - 1,

        // elements before (k-1) are preserved
        forall|i: int|
            0 <= i < (k - 1) as int ==> new_list[i] == list[i],

        // elements after (k-1) shift left by 1
        forall|i: int|
            (k - 1) as int <= i < new_list.len() as int ==> new_list[i] == list[i + 1],

        // equivalently: new_list is list with index (k-1) removed
        forall|j: int|
            0 <= j < list.len() as int && j != (k - 1) as int
            ==> new_list[if j < (k - 1) as int { j } else { j - 1 }] == list[j],
{
    let idx = k - 1; // convert to 0-based index

    let mut new_list = Vec::with_capacity(list.len() - 1);
    new_list.extend_from_slice(&list[..idx]);      // elements before k
    new_list.extend_from_slice(&list[idx + 1..]);  // elements after k

    new_list
}

} // verus!

